#  YKAY EDUPORTAL - PHASE 3F INGESTION SCRIPT (Base64 edition)
#  Live Dashboards + Production Portal Page + IT Education Portal
#  Target: C:\Users\USER\Desktop\PROJECTS\ykay_edu\envoys-site
#  Compatible with Windows PowerShell 5.1 and PowerShell 7+
#
#  Files are embedded as Base64 so the script survives any
#  line-ending or encoding changes during download/transfer.
#
#  RECOMMENDED: run on branch phase/3f-dashboards-it-portal
# ============================================================

$ProjectRoot = "C:\Users\USER\Desktop\PROJECTS\ykay_edu\envoys-site"

if (-not (Test-Path $ProjectRoot)) {
    Write-Host "ERROR: Project root not found at $ProjectRoot" -ForegroundColor Red
    exit 1
}

function Write-ProjectFileB64 {
    param(
        [string]$RelativePath,
        [string[]]$Chunks
    )
    $FullPath = Join-Path $ProjectRoot $RelativePath
    $Dir = Split-Path $FullPath -Parent
    if ($Dir -and -not (Test-Path $Dir)) { New-Item -ItemType Directory -Path $Dir -Force | Out-Null }
    $Base64 = [string]::Join("", $Chunks)
    $Bytes = [System.Convert]::FromBase64String($Base64)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    Write-Host ("Updated " + $RelativePath + " (" + $Bytes.Length + " bytes)") -ForegroundColor Green
}

